\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://4665/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 99r-102v}}\plain \f1\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\b\lang1033\fs22\chcbpat17 Gebetszyklus von 40 Mahnungen zu Christus}}
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 >H<erre Iesus Criste, ich mon vnd pit dich deines gotlichen wesen vnd aller gute}}\plain \f1\i\lang1033\fs22 , die wesenleich in dir vereinet sind, das du alle naturleiche gu\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs22 t, die du in meiner sele geschaffen hast, sterkest vnd volbringest in die werk geistleicher volkumenheit ...\~\endash \~... das du mich des alles tailheftig tust hieczu\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs22  ein stewr zu den genaden, abla\u223 \'df der sunden, merung der tugent vnd nach diesem leben zu\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs22  einer uber u\u223 \'df deiner go\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs22 tleichen frewden mit dir czu nye\u223 \'dfen im himelreich an ende. Amen.
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20 Parallel\u252 \'fcberlieferung: {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Augsburg, UB, III.1.4\u176 \'b05}}\plain \f1\lang1033\fs20 , Bl. 304r-309v (aus dem Dominikanerinnenkloster Heiliggrab zu Bamberg); {\field{\*\fldinst HYPERLINK "hida://5007[1].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Gotha, FB, Chart. B 938}}\plain \f1\lang1033\fs20 , Bl. 2r-28v (mittelbair.); {\field{\*\fldinst HYPERLINK "hida://5007[2].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 M\u252 \'fcnchen, BSB, Cgm 836}}\plain \f1\lang1033\fs20 , Bl. 245r-249v (aus Rebdorf); {\field{\*\fldinst HYPERLINK "hida://5007[3].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 N\u252 \'fcrnberg, GNM, Hs 114263 a}}\plain \f1\lang1033\fs20 , Bl. 1r-12v; {\field{\*\fldinst HYPERLINK "hida://5007[4].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 N\u252 \'fcrnberg, Stadtbibl., Will 7.1447.8\u176 \'b0}}\plain \f1\lang1033\fs20 , Bl. 60v-67v (beide aus dem N\u252 \'fcrnberger Katharinenkloster). \endash  \u220 \'dcberlieferungsnachweise: \plain \f1\scaps\lang1033\fs20 Schneider\plain \f1\lang1033\fs20 , Dt. Hss. Augsburg, S. 259. In Augsburg, UB, III.1.4\u176 \'b05 erscheint dieser Gebetszyklus ebenfalls als Anhang zu Seuses \lquote B\u252 \'fcchlein der ewigen Weisheit\rquote , in N\u252 \'fcrnberg, Stadtbibl., Will 7.1447.8\u176 \'b0 als Anhang nur zu dem dritten Teil des \lquote B\u252 \'fcchleins\rquote , den \lquote Hundert Betrachtungen\rquote .}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

\uc1
\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://4665/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 103r-111v}}\plain \f1\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\b\lang1033\fs22\chcbpat17 Traktat \u252 \'fcber Tugenden von Klosterfrauen (Nachtrag)}}
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 >Z<u lobe vnd zu ere vnserm lieben herren Ihesu Cristi, dem preutigam der junckfraun}}\plain \f1\i\lang1033\fs22 , vnd zu raiczen die junckfrawen vnd ander menschen zw zu nemen in den tugenden, an die junckfrauen wenig got geuallent schreib ich dicz kurcz puchlein, vnd das auch nucz ist, ist daz du wild zu nemen in dem geist vnd in dem, durch des wille das das geschehe. Du pist kumen zu der schul der tugende, das ist zu junckfrawlicher rainikait, die do mu\u223 \'df besliessen vil tugend, die sie zieren ... Czu dem ersten: Pis stetes vnder einem solhem an weiser vnd maister oder lerer, der der lere volget vnd si selber volbringt, als du magst ...\~\endash \~... vnd mercke das wesen deins herczen vnd leichnams, was dir geprech, ob du zu oder ab nemst, was hinder dem zu nemen, vnd dem scholtu begegen eint wider mit flihen oder wider streiten oder in ander wei\u223 \'df, die sunde sind zu fliehen den po\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs22 sen ...\plain \f1\lang1033\fs22  (Text bricht ab.)
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20 Parallel\u252 \'fcberlieferung: {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 N\u252 \'fcrnberg, Stadtbibl., Cent.VI,46f}}\plain \f1\lang1033\fs20 , Bl. 163r-174v (aus dem N\u252 \'fcrnberger Dominikanerinnenkloster St. Katharina, Mitte 15. Jh.); vgl. \plain \f1\scaps\lang1033\fs20 Schneider\plain \f1\lang1033\fs20 , Dt. Hss. N\u252 \'fcrnberg, S. 155. Am Schluss fehlt Text im Umfang von etwa einer Seite; das Fehlende entspricht Bl. 174r-v der N\u252 \'fcrnberger Hs. (freundliche Auskunft von Christine Sauer, N\u252 \'fcrnberg). \endash  Zur Gattung vgl. Ekkehard \plain \f1\scaps\lang1033\fs20 Borries\plain \f1\lang1033\fs20 , Schwesternspiegel im 15. Jahrhundert. Gattungskonstitution, Editionen, Untersuchungen, Berlin/New York 2008, mit Auflistung der Texte S. 489-492 (ohne diesen Text).}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}{\f2\fnil\fcharset238 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

\uc1
\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://4665/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 112r-145v}}\plain \f1\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6922/?u"}{\fldrslt \plain \f1\b\lang1033\fs22\chcbpat17 \lquote Messerkl\u228 \'e4rung}}\plain \f1\b\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\i\lang1033\fs22\chcbpat17 Man findet vil buechlein vnd lere}}\plain \f1\b\lang1033\fs22 \rquote 
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs22 (112r-v Register:) \plain \f1\i\lang1033\fs22 >i< Wo von di\u223 \'df puchelein sag vnd war an die me\u223 \'dfe sey vnd was sie sey. >ii< Das funf ding in der me\u223 \'dfe geschechen ...\plain \f1\lang1033\fs22  (113r-145v Text:) \plain \f1\i\lang1033\fs22 >Erst capitel.< {\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Man findet vil puchelein vnd lere, die da von sagen, was die dink vnd czeichen bedewten, die in der me\u223 \'dfe geschehen, aber mein begirde ist, das ich aller liebst dir czue versten geben wellen, wie du me\u223 \'df horen scholste, das es got ein ere werde}}\plain \f1\i\lang1033\fs22  ...\~\endash \~... Dar vmb pit ich ein igleichen menschen, der di\u223 \'df pu\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs22 chlein lesen vnd dar nach sich vben wirt, das er vnsern herren fur mich pit, das er mein gepreche erfulle ..., das ich in das ewig leben vnd clares liecht geleichtet werde, do ich ewigkleichen in selikeit pey im beleibe. Amen. >Ora pro me, mater misericordie.<
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20 Edition: Franz Xaver \plain \f1\scaps\lang1033\fs20 W\plain \f1\scaps\lang1033\fs20 \u246 \'f6\plain \f1\scaps\lang1033\fs20 ber\plain \f1\lang1033\fs20 , Ain guett ler von der mess tzu nuz vnd haill allen layen durch Nicolaum Tzipser. Anno domini M.C.D.L.X.X. Aus der handschrift hg. und mit einer gegen\u252 \'fcberstehenden \u252 \'fc\plain \f2\lang1024\fs20 bersetzung versehen, in: Jahresbericht des k.k. Obergymnasiums zu Przemy\u347 \'9cl f\u252 \'fcr das Schuljahr 1855/6, Przemy\u347 \'9cl 1856, S. 3-52 (nach der Handschrift {\field{\*\fldinst HYPERLINK "hida://5007[1].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Warschau, Nationalbibl., Cod. 8033 III [olim: Przemy\u347 sl (Polen), Bibl. des griech.-kath. Domkapitels, Nr. 18 (III D 3, XLVIII G 4)],}}\plain \f1\lang1033\fs20  mit einem zus\u228 \'e4tzlichen Prolog, Text mit Register beginnt S. 9). \endash  \u220 \'dcberlieferung: Kurt \plain \f1\scaps\lang1033\fs20 Illing\plain \f1\lang1033\fs20 , \lquote Me\u223 \'dferkl\u228 \'e4rung \plain \f1\i\lang1033\fs20 Man findet vil bu\plain \f1\i\super\lang1033\fs20 e\plain \f1\i\lang1033\fs20 chlein vnd lere\rquote \plain \f1\lang1033\fs20 , in: \plain \f1\super\lang1033\fs20 2\plain \f1\lang1033\fs20 VL 6 (1987), Sp. 443-446 und 11 (2004), Sp. 994; http://www.handschriftencensus.de/werke/5079. Bisher 7 Hss. nachgewiesen (darunter 3 aus dem N\u252 \'fcrnberger Katharinenkloster); diese Hs. bisher unbekannt.
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 Die Messerkl\u228 \'e4rung ist im {\field{\*\fldinst HYPERLINK "hida://bezwrk[2].6923/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Bistum Bamberg}}\plain \f1\lang1033\fs20  entstanden, wie aus einer Stelle Bl. 136v (=\~Ed., S. 43) hervorgeht: \plain \f1\i\lang1033\fs20 So hat der erwirdig herre her Albrecht Byschoff zu Babenwerk\plain \f1\lang1033\fs20  ({\field{\*\fldinst HYPERLINK "hida://bezper[1].4100/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Albrecht von Wertheim, F\u252 \'fcrstbischof zu Bamberg}}\plain \f1\lang1033\fs20  1398-1421) \plain \f1\i\lang1033\fs20 allen seinen vndertan gepoten, das man in allen kirchen ein teflein, dar an die marter vnsers herren gemalt sey, haben vnd in der me\u223 \'dfe den ku\u223 \'df des frides geben sullen, vnd hat vierczig tag ablas dar zu geben allen den, die den ku\u223 \'df in der me\u223 \'df nemen vnd des kusses bedeutung da mit betrachten\plain \f1\lang1033\fs20 .}

