\pard\fi135\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20 5) Nach Bl. 12 als Falz {\field{\*\fldinst HYPERLINK "hida://5360[0]/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 0,5\~x\~5,5}}\plain \f1\lang1033\fs20  cm gro\u223 \'dfer {\field{\*\fldinst HYPERLINK "hida://5260[0]/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Pergamen}}\plain \f1\lang1033\fs20 tstreifen, mit Resten einer {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6922/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Zeichnung}}\plain \f1\lang1033\fs20  und den Buchstaben \plain \f1\i\lang1033\fs20 Jo\plain \f1\lang1033\fs20 , m\u246 \'f6glicherweise Bruchst\u252 \'fcck eines {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Notariatssignets}}\plain \f1\lang1033\fs20  und damit vielleicht Rest der von \plain \f1\scaps\lang1033\fs20 Borchling\plain \f1\lang1033\fs20  erw\u228 \'e4hnten {\field{\*\fldinst HYPERLINK "hida://bezwrk[2].6922/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Urkunde}}\plain \f1\lang1033\fs20  (s.\~o.), die ehemals als Spiegel des jetzt verlorenen Vorderdeckels diente.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

