\par \pard\fi0\li0\qj\ri-285\sb0\sa0\itap0 \plain \f1\i\lang1033\fs22 >Orison a nostre seigneur Ihesu Crist per contemplacion.< >{\field{\*\fldinst HYPERLINK "hida://5650[1].5666v/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Doulx Ihesuchrist, ie proteste deuant toy, confesse et congnois la foy fermement}}\plain \f1\i\lang1033\fs22  ...\~\endash \~... ou tu pendis pour nostre redemption. En nom du pere et du filz et du saint esperit. Amen.
\par \pard\fi0\li0\qj\ri-285\sb0\sa0\itap0 \plain \f1\lang1033\fs20 Abdruck nach {\field{\*\fldinst HYPERLINK "hida://5007[1].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Kopenhagen, Det kongelige Bibliotek, GKS 1612\~4\u176 \'b0, Bl. 37bisr-bisv}}\plain \f1\lang1033\fs20 : http://manuscripts.org.uk/\-chd.dk/gui/gks1612_gui3.html. (Digitalisat: http://www.kb.dk/permalink/2006/manus/279/eng/37+bis+verso/?var=). Weitere \u220 \'dcberlieferung: {\field{\*\fldinst HYPERLINK "hida://5007[2].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Gent, UB, 234, Bl. 108}}\plain \f1\lang1033\fs20 v; {\field{\*\fldinst HYPERLINK "hida://5007[3].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Paris, BNF, fr. 13168, Bl. 3r-5r}}\plain \f1\lang1033\fs20 ; {\field{\*\fldinst HYPERLINK "hida://5007[4].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 ebd., lat. 10561, Bl. 101v}}\plain \f1\lang1033\fs20  (vgl.\plain \f2\lang1033\fs20  \plain \f1\lang1033\fs20 Jean \plain \f1\scaps\lang1033\fs20 Sonet\plain \f1\lang1033\fs20 , R\u233 \'e9pertoire d\rquote incipit de pri\u232 \'e8res en ancien fran\u231 \'e7ais, Genf 1956, S. 235, Nr. 1314; \plain \f1\scaps\lang1033\fs20 Leroquais\plain \f1\lang1033\fs20 , Livres d\rquote heures II, S. 27). }

