\par \pard\fi0\li0\qj\ri-285\sb0\sa0\itap0 \plain \f1\i\lang1033\fs22 >D<{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 omine, labia mea aperies, et os meum annunciabit laudem tuam}}\plain \f1\i\lang1033\fs22  ... >P<{\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 atris sapiencia veritas diuina, deus homo captus est hora matutina}}\plain \f1\i\lang1033\fs22  ...\plain \f1\lang1033\fs22  ({\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 AH 30, Nr. 13,1}}\plain \f1\lang1033\fs22 ). \plain \f1\i\lang1033\fs22 >{\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6922/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Antiphona}}\plain \f1\i\lang1033\fs22 .< {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Adoramus te, Criste, et benedixi\-mus}}\plain \f1\i\lang1033\fs22  \plain \f1\lang1033\fs22 (!) \plain \f1\i\lang1033\fs22 tibi, quia per sanctam crucem tuam redemisti mundum\plain \f1\lang1033\fs22  ({\field{\*\fldinst HYPERLINK "hida://bezlit[1].8330/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 CAO 1287}}\plain \f1\lang1033\fs22 ). \plain \f1\i\lang1033\fs22 >{\field{\*\fldinst HYPERLINK "hida://bezwrk[2].6922/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Oracio}}\plain \f1\i\lang1033\fs22 .< {\field{\*\fldinst HYPERLINK "hida://5650[4].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Domine Ihesu Criste, filii dei viui, pone passionem, crucem et mortem tuam}}\plain \f1\i\lang1033\fs22  ...\~\endash \~... {\field{\*\fldinst HYPERLINK "hida://5650[5].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Hora nona dominus Ihesus expirauit}}\plain \f1\i\lang1033\fs22  ...\plain \f1\lang1033\fs22  ({\field{\*\fldinst HYPERLINK "hida://bezlit[2].8330/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 AH 30, Nr. 13,5}}\plain \f1\lang1033\fs22 ). \pla