\par \pard\fi0\li0\qj\ri-285\sb0\sa0\itap0 \plain \f1\lang1033\fs22 (Anfang fehlt wegen Blattverlust) [...] \plain \f1\i\lang1033\fs22 deus, da nobis illam sancti spiritus graciam, quam discipulis tuis in die sancto penthecostes transmisisti. Qui viuis. >Prime.< >D<eus, in adiutorium. >D<{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 e virgine Maria Cristus fuit natus, crucifixus, mortuus atque tumulatus}}\plain \f1\i\lang1033\fs22  ...\plain \f1\lang1033\fs22  ({\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 AH 30, Nr. 5,2}}\plain \f1\lang1033\fs22 ). {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Veni sancte spiritus}}\plain \f1\i\lang1033\fs22  \plain \f1\lang1033\fs22 ({\field{\*\fldinst HYPERLINK "hida://bezlit[1].8330/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 CAO 5327}}\plain \f1\lang1033\fs22 ). \plain \f1\i\lang1033\fs22 >{\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Oracio}}\plain \f1\i\lang1033\fs22 .< {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Omnipotens sempiterne deus}}\plain \f1\i\lang1033\fs22  ...\~\endash \~... >{\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6922/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Recommendacio}}\plain \f1\i\lang1033\fs22 .< Has horas canonicas cum deuotione tibi, sancte spiritus, pia racione ... vt viuamus iugiter celi regione. Amen\plain \f1\lang1033\fs22  ({\field{\*\fldinst HYPERLINK "hida://bezlit[2].8330/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 AH 30, Nr. 5,8}}\plain \f1\lang1033\fs22 ).
