\pard\fi0\li0\qj\ri-285\sb0\sa0\itap0 \plain \f1\b\lang1033\fs22 b.\plain \f1\lang1033\fs22  ({\field{\*\fldinst HYPERLINK "hida://4665/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 116r-118v}}\plain \f1\lang1033\fs22 ) {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\b\lang1033\fs22\chcbpat17 Sieben Bittgebete an Christus}}\plain \f1\b\lang1033\fs22 , {\field{\*\fldinst HYPERLINK "hida://5710[0]/?u"}{\fldrslt \plain \f1\b\lang1033\fs22\chcbpat17 frz.}}\plain \f1\b\lang1033\fs22  \plain \f1\i\lang1033\fs22 >Les .vii. requestes\plain \f1\lang1033\fs22 .< (Einleitung:) {\field{\*\fldinst HYPERLINK "hida://5650[0].5666v/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Qui conques voeult estre bien conseillies de la chose}}\plain \f1\i\lang1033\fs22 , dont il a\plain \f1\lang1033\fs22  [116v] \plain \f1\i\lang1033\fs22 grant mestier, si die chacun iour acoustemement ces orisons, que vous trouueres sy escriptes, et sachies que \plain \f1\b\i\lang1033\fs22 celuy ou celle\plain \f1\i\lang1033\fs22  qui les dira, desconforte ne moira ne desconseille ne sera le iour qui les dira, et appres chascune orison dites Pater noster au long.\plain \f1\lang1033\fs22  (Gebete:) {\field{\*\fldinst HYPERLINK "hida://5650[1].5666v/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Doulz douls pere, saincte trinite et vng dieu, biau sire diex, ie vous requier conseil et aide en lhonneur de celui conseil que vous preistes de vostre propre sapience}}\plain \f1\i\lang1033\fs22 , quant vous envoiastes vostre saint angle Gabriel ala vierge Marie dire et\plain \f1\lang1033\fs22  [117r] \plain \f1\i\lang1033\fs22 annuncier la nouuelle de nostre salut ...\~\endash \~... Huy seras en paradis auent moy. Sire, si comme ce fust voir, regardes moy en pitie. Pater noster.
\par \pard\fi0\li0\qj\ri-285\sb0\sa0\itap0 \plain \f1\lang1033\fs20 Textabdrucke (jeweils ohne Einleitung): \plain \f1\scaps\lang1033\fs20 Leroquais\plain \f1\lang1033\fs20 , Livres d\rquote heures II, S. 309f.; \plain \f1\scaps\lang1033\fs20 Suchier\plain \f1\lang1033\fs20  (s.\~o. zu Bl. 112r), S. 284f.; \plain \f1\scaps\lang1033\fs20 Holder\plain \f1\lang1033\fs20  (s.\~o. zu Bl. 112r), S. 640f. Abdruck der Einleitung: \plain \f1\scaps\lang1033\fs20 Leroquais\plain \f1\lang1033\fs20 , Livres d\rquote heures, I, S. XXVIII. \endash  \u220 \'dcberlieferung: ebd., II, S. 402 und 444 (Register). Vgl. auch \plain \f1\scaps\lang1033\fs20 Sonnet\plain \f1\lang1033\fs20 , Incipit, S. 91, Nr. 504.}

