\uc1
\pard\fi0\li0\qj\ri-285\sb0\sa0\itap0 \plain \f1\b\lang1033\fs22 b.\plain \f1\lang1033\fs22  ({\field{\*\fldinst HYPERLINK "hida://4665/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 9va-17ra}}\plain \f1\lang1033\fs22 ) {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6922/?u"}{\fldrslt \plain \f1\b\lang1033\fs22\chcbpat17 Schmuck und Kleidung der Braut}}
\par \pard\fi0\li0\qj\ri-285\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Nu merke vort, wellek din smyde sy vnde wat dine kledinge scal sin}}\plain \f1\i\lang1033\fs22 , dar du dy wol mede behegheliken scolt wysen vor deme heren. Tho deme ersten se, datu din antlat dwat in deme vatere vnde blode Ihesu Cristi, dat vthe siner siden vlot ...\plain \f1\lang1033\fs22  (10vb) \plain \f1\i\lang1033\fs22 Tho deme anderen male se, datu vorest vrolicheit vnde blidicheit an dyme ghemote ...\plain \f1\lang1033\fs22  (11rb) \plain \f1\i\lang1033\fs22 Tho deme drudden male so scoltu dy vor synen ogen cleden vnde syren myt dogeden ...\plain \f1\lang1033\fs22  (12ra) \plain \f1\i\lang1033\fs22 Tho deme souenden male so scoltu vmme nemen den mantel der leue ...\plain \f1\lang1033\fs22  (12va) \plain \f1\i\lang1033\fs22 Tho deme lesten se, datu gesiret sist vnde ghecledet myt sedeliken dogeden, myt gotliken dogeden, de got suluen an dyner selen heft ghevracht. Der sint dre: Dat is loue\plain \f1\lang1033\fs22  [Glauben], \plain \f1\i\lang1033\fs22 de dine ogen opent ...\plain \f1\lang1033\fs22   (13vb) \plain \f1\i\lang1033\fs22 Dat ander clet dyner sele, dat dy wert van gode gesent, dat is hopene ...\plain \f1\lang1033\fs22  (14ra) \plain \f1\i\lang1033\fs22 Dat drudde clet, dat dy got van bouen sent, dat is leue ...\plain \f1\lang1033\fs22  (15vb) \plain \f1\i\lang1033\fs22 Na dessen gotliken dogeden dar volget en +oget na, dar du walt vnde herschop mede krigest ouer alle dine werke ...\plain \f1\lang1033\fs22  (16ra) \plain \f1\i\lang1033\fs22 De erste doget, dat is wysheit, datu scolt merken alle werke godes ... De andere doget het vorstentnisse ... De drudde doget, dat is wetenheit ...\plain \f1\lang1033\fs22  (16rb) \plain \f1\i\lang1033\fs22 De verde doget is vnde het kunst ... De vefte het inwendich klukheit ... Desse klokheit mostu in dy merken by velen tekenen ...
\par \pard\fi0\li0\qj\ri-285\sb0\sa0\itap0 \plain \f1\lang1033\fs20 Vgl. {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Gh, Bl. 62ra-65va}}\plain \f1\lang1033\fs20 .}

