\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://4665/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 161r-177v}}\plain \f1\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://bezper[1].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs22\chcbpat17 Simon Grunau}}\plain \f1\b\lang1033\fs22 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6923/?u"}{\fldrslt \plain \f1\b\lang1033\fs22\chcbpat17 Preu\u223 \'dfische}}\plain \f1\b\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://bezwrk[2].6922/?u"}{\fldrslt \plain \f1\b\lang1033\fs22\chcbpat17 Chronik}}\plain \f1\b\lang1033\fs22 , Ausz\u252 \'fcge, die Ketzerei der Deutschordensbr\u252 \'fcder zum Gegenstand haben (mit Reformation am Schluss)}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}{\f2\fnil\fcharset238 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

