\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20 Beginn der Sequenz {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 AH 54, Nr. 218}}\plain \f1\lang1033\fs20  (De beata Maria virgine), s. u. Fasz. II, 77\plain \f1\super\lang1033\fs20 ra-va\plain \f1\lang1033\fs20 , Nr. 60.
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\b\lang1033\fs20 De beata Maria virgine\plain \f1\lang1033\fs20 , \plain \f1\i\lang1033\fs20 >V<{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs20\chcbpat17 erbum bonum et suaue}}\plain \f1\i\lang1033\fs20  / perso\plain \f1\lang1033\fs20 [nemus, illud Aue, ...], vgl. AH 54, Nr. 218}

