\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 [laut Inh.verzeichnis 1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Item auctoritates diuerse doctorum diuersorum 46}}\plain \f1\i\lang1033\fs24  et infra\plain \f1\lang1033\fs24 , \plain \f1\i\lang1033\fs24 Item de prelatis 50 et infra et inuenies quam plura\plain \f1\lang1033\fs24 , vgl. 51\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  (alte Foliierung: \plain \f1\i\lang1033\fs24 50\plain \f1\lang1033\fs24 ) am oberen Seitenrand: \plain \f1\i\lang1033\fs24 De prelatis\plain \f1\lang1033\fs24 ].}

