\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 124\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 -127\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930gi/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Speculum amatorum mundi}}\plain \f1\lang1033\fs24 .
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\i\lang1033\fs24 >Incipit speculum amatorum mundi<.\plain \f1\lang1033\fs24  (124\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 )\plain \f1\i\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 >U<Idete quomodo caute ambuletis }}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 ... (Eph 5,15-17).}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17  Apostolus Paulus, conscius consiliorum dei, sciens, quod infinite sunt}}\plain \f1\i\lang1033\fs24  delicie celestis patrie, quas nec oculus vidit nec auris audivit ... - ... videant, quomodo se preparent ad futura.
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20 Der h\u228 \'e4ufig \u252 \'fcberlieferte Text wird verschiedenen Autoren ({\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs20\chcbpat17 Bernardus Senensis}}\plain \f1\scaps\lang1033\fs20 , {\field{\*\fldinst HYPERLINK "hida://bezper[1].4100/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs20\chcbpat17 Dionysius Carthusianus}}\plain \f1\scaps\lang1033\fs20 , {\field{\*\fldinst HYPERLINK "hida://bezper[2].4100/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs20\chcbpat17 Henricus de Langenstein}}\plain \f1\scaps\lang1033\fs20 , {\field{\*\fldinst HYPERLINK "hida://bezper[3].4100/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs20\chcbpat17 Nicolaus de Dinkelsb\u252 \'fchl}}\plain \f1\lang1033\fs20  u. a.) zugeschrieben. Der Text der Hs. weicht am Schluss vom Druck ab. Druck: Sancti Bernardini Senensis ordinis Seraphici Minorum Opera omnia ..., Bd. 3, verb. Neuaufl. Venedig 1745, S. 437-440; Doctoris Ecstatici D. Dionysii Cartusiani Opera omnia ..., Bd. 39 (Opera minora 7), Montreuil 1910, S. 485-495.
\par \pard\sl252\slmult1\fi0\li0\ql\ri0\sb0\sa165\itap0 Zur \u220 \'dcberlieferung (Auswahl, jeweils ohne diese Hs.) vgl. \plain \f1\scaps\lang1033\fs20 Bloomfield\plain \f1\lang1033\fs20 , Incipits und Suppl., Nr. 6443; \plain \f1\scaps\lang1033\fs20 Mohan\plain \f1\lang1033\fs20 , Initia\plain \f1\scaps\lang1033\fs20 , \plain \f1\lang1033\fs20 Nr.\plain \f1\scaps\lang1033\fs20  489; Madre\plain \f1\lang1033\fs20 , Nikolaus von Dinkelsb\u252 \'fchl, S. 297, Nr. 6 (unter den Opera dubia); CCCM 121, S. 149, 584-588 (588 Hss. genannt); \plain \f1\scaps\lang1033\fs20 Bange\plain \f1\lang1033\fs20 , Spiegels der Christenen, S. 58f., 266. Weitere Lit. zur \u220 \'dcberlieferung in der Beschreibung von Bertram \plain \f1\scaps\lang1033\fs20 Lesser\plain \f1\lang1033\fs20  zu: Wolfenb\u252 \'fcttel, HAB, {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Cod. Guelf. 419 Helmst.}}\plain \f1\lang1033\fs20 , 109\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs20 -113\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs20 , vgl. http://diglib.hab.de/?db=mss&list=ms&id=419-helmst&catalog=Lesser.}

