\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\b\lang1033\fs24 24.\plain \f1\lang1033\fs24  (138\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 , Z. 24-36) \plain \f1\i\lang1033\fs24 Ad quam salubritatem fugiendum hortatur nos beatus Bernardus dicens: {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Confuge ad urbem refugii}}\plain \f1\i\lang1033\fs24  \u8230 \'85 - \u8230 \'85 et ad futuram gloriam que promittitur.\plain \f1\lang1033\fs24  (138\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 , Z. 36 - 138\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 , Z. 2)\plain \f1\lang1033\fs20  \plain \f1\i\lang1033\fs24 Huius religiose uite utilissimum factum \plain \f1\lang1033\fs24 (?)\plain \f1\i\lang1033\fs24  declarat idem in hec uerba:\plain \f1\i\lang1033\fs20  \plain \f1\i\lang1033\fs24 O vita secura, ubi consciencia pura \plain \f1\lang1033\fs24 [\plain \f1\scaps\lang1033\fs24 Bernardus\plain \f1\lang1033\fs24 : Ad milites templi, 2,3]\plain \f1\i\lang1033\fs24  \u8230 \'85 - \u8230 \'85 et cum deuotione acceptatur. Hec ille.
\par \pard\sl252\slmult1\fi0\li0\ql\ri0\sb0\sa165\itap0 {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs20\chcbpat17 Bonaventura}}\plain \f1\lang1033\fs20 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Soliloquium}}\plain \f1\lang1033\fs20 , cap. 2 und 3, Druck: Bonaventurae opera, Bd. 8, S. 45f., 53, vgl. \plain \f1\i\lang1033\fs20 B\plain \f1\lang1033\fs20 , 20\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 , s. o. Nr. 8 und 19;}

