\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\b\lang1033\fs24 26. \plain \f1\lang1033\fs24 (138\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 , Z. 22 - 140\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 , Z. 18)\plain \f1\lang1033\fs20  {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Vt autem huius vite salutifer amor in nobis magis crescat}}\plain \f1\i\lang1033\fs24  tractatum quadam de laude vite solitarie, qui secundum quosdam dicitur compositus a Petro Damiani, secundum alios a beato Gregorio pape, secundum quosdam vero a beato Basilio episcopo \u8230 \'85 et illius tenor talis est. >L<Iber de singularis vite meritis pauca perstringere \u8230 \'85 - \u8230 \'85 ad edificatam perueniet domum non manufactam eternam in celis. Ipso prestante qui cum patre et spiritu sancto uiuit et regnat deus in secula seculorum. Amen. \plain \f1\lang1033\fs24 Rest von 140\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24  leer.
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs20\chcbpat17 Petrus Damiani}}\plain \f1\lang1033\fs20 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930gi/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Liber qui dicitur \u8222 \'84Dominus vobiscum\ldblquote }}\plain \f1\lang1033\fs20 , cap. 19, auch \u252 \'fcberliefert als {\field{\*\fldinst HYPERLINK "hida://bezper[1].4100/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs20\chcbpat17 Ps.-Basilius Magnus}}\plain \f1\lang1033\fs20 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6930/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 De laude vitae solitariae}}\plain \f1\lang1033\fs20 , Druck: PL 145, Sp. 246-251, Ed. K. \plain \f1\scaps\lang1033\fs20 Riendel\plain \f1\lang1033\fs20  (Hg.), Die Briefe des Petrus Damiani (MGH, Briefe der dt. Kaiserzeit 4,1), M\u252 \'fcnchen 1983, Bd. 1, S. 272-278, vgl. \plain \f1\i\lang1033\fs20 B\plain \f1\lang1033\fs20 , 20\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 -23\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 .}

