\uc1
\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://4665/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 1}}\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -4\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Missale}}\plain \f1\b\lang1033\fs24 , Fragment: {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6922/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Pro defunctis}}\plain \f1\b\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[2].6922/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 In Anniversario defunctorum}}\plain \f1\b\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[3].6922/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 In Purificatione BMV}}\plain \f1\b\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[4].6922/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Consecratio cereorum}}\plain \f1\lang1033\fs24 .
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20 Da es sich um die inneren Doppelbl\u228 \'e4tter einer Lage handelt, besteht direkter Textanschluss. Im Totenged\u228 \'e4chtnis Gebete f\u252 \'fcr die Verstorbenen am 1., 2., 3., 7. und 30. Tag (vgl. 1\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 -2\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 ) sowie j\u228 \'e4hrliches Anniversarium (vgl. 2\plain \f1\super\lang1033\fs20 r-v\plain \f1\lang1033\fs20 ), dabei jeweils maskuline und feminine Formen (z. B. 1\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20  \plain \f1\i\lang1033\fs20 ut ancilla\plain \f1\lang1033\fs20  [tua \u183 \'b7N\u183 \'b7], 2\plain \f1\super\lang1033\fs20 v\plain \f1\i\lang1033\fs20  animabus famulorum famularumque tuarum\plain \f1\lang1033\fs20 ) vorgesehen, bzw. interlinear die alternativen weiblichen Endungen erg\u228 \'e4nzt (z. B. 2\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 ).
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 Ein stichprobenartiger Vergleich mit dem Missale Swerinense von 1479 (verf\u252 \'fcgbar \u252 \'fcber die USUARIUM-DB: https://usuarium.elte.hu/book/11/view, wohl identisch mit {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 GW M24768}}\plain \f1\lang1033\fs20 : Missale Sverinense. [Rostock: Fratres Domus Viridis Horti, um 1480], im Folgenden: Miss. Swer. 1479, Bild ...) ergab auff\u228 \'e4llige \u220 \'dcbereinstimmungen, bei teilweiser Umstellung der Reihenfolge der Gebete und Ges\u228 \'e4nge.\plain \f1\lang1033\fs24\cf6  \plain \f1\lang1033\fs20 Die Gebete teilweise verzeichnet im Corpus orationum (CO), vgl. CCSL 160, 160A-J.
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 Die am unteren Rand von 1\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 -4\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20  nachgetragenen Gebete f\u252 \'fcr die Messen \u8218 \'82Pro his, qui in cimiterio requiescunt\lquote , \u8218 \'82Pro fratribus, familiaribus et benefactoribus\lquote  und \u8218 \'82Pro parentibus\lquote  stimmen in dieser Reihenfolge mit dem dominikanischen Usus \u252 \'fcberein, s. u. Inhalt. F\u252 \'fcr einen Ordenskontext sprechen auch die Gebete f\u252 \'fcr die congregatio sowie f\u252 \'fcr sorores et fratres.}

