\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\i\lang1033\fs24 Sermo de Annunciacione. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 >H<ec dies, quam fecit dominus ... }}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 (Ps 117,24).}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17  Uerba ista conuenienter assumi possunt}}\plain \f1\i\lang1033\fs24  ad commendacionem presentis diei Annunciacionis, videlicet uirginis glo\plain \f1\lang1033\fs24 (164\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 )\plain \f1\i\lang1033\fs24 riose ... - ... nec cor hominis possit cogitare, quod nobis donare dignetur Christus filius etc.
\par \pard\sl252\slmult1\fi0\li0\ql\ri0\sb0\sa165\itap0 \plain \f1\lang1033\fs20 In den Sermones de tempore (Series 2.) des \plain \f1\scaps\lang1033\fs20 Jordanus de Quedlinburg\plain \f1\lang1033\fs20  eine Predigt mit diesem Incipit, aber abweichendem Explicit (Laetamini in domino ...) verzeichnet bei \plain \f1\scaps\lang1033\fs20 Schneyer\plain \f1\lang1033\fs20 , Repertorium III, {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 S. 848, Nr. 407}}\plain \f1\lang1033\fs20 ,}

