\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\i\lang1033\fs24 >M<{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Mittite }}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 (!) }}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 partes eius }}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 [korrigiert:}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17  eis}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 ]}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17  ...}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17  (II Esr 8,10). [am Rand vom Schreiber Predigtbeginn nachgetragen:] }}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Consuetudo est}}\plain \f1\i\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 [in]}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17  mundo}}\plain \f1\i\lang1033\fs24 , \plain \f1\lang1033\fs24 [quando]\plain \f1\i\lang1033\fs24  aliquis usque ad mortem \plain \f1\lang1033\fs24 [mit Einf\u252 \'fcgungszeichen im Haupttext fortgesetzt:] \plain \f1\i\lang1033\fs24 mortem cruciatur, mittit admicos \plain \f1\lang1033\fs24 [lies: ad amicos] \plain \f1\i\lang1033\fs24 suos dilectissimos ... - ... oraciones maxime prosunt animabus, qui in purgatorio sunt: Requiem eternam, dona eis ...\plain \f1\lang1033\fs24 ;
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20 Eine Predigt mit \u228 \'e4hnlichen Incipit bei \plain \f1\scaps\lang1033\fs20 Schneyer\plain \f1\lang1033\fs20 , Repertorium, V, {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 S. 432, Nr. 49}}\plain \f1\lang1033\fs20  einem \plain \f1\scaps\lang1033\fs20 Sifridus (Niger?)\plain \f1\lang1033\fs20  OP (ca. 1320-40, mgr. Oxoniae) zugeschrieben, hier auch Angaben zur Einzel\u252 \'fcberlieferung dieser Predigt;}

