\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 175\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 -182\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930gi/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Collectio miraculorum de beata Maria virgine}}\plain \f1\lang1033\fs24 .
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20 Sammlung von 37 mit der Gottesmutter Maria verbundenen Wundererz\u228 \'e4hlungen. Die einzelnen St\u252 \'fccke mit Ausnahme von Nr. 10, 12, 19, 22, 23, 25, 29, 30, 34 und 37 bei \plain \f1\scaps\lang1033\fs20 Poncelet\plain \f1\lang1033\fs20 , Index miraculorum BMV, verzeichnet. Bei \plain \f1\scaps\lang1033\fs20 Poncelet\plain \f1\lang1033\fs20  teilweise Angabe zu den Quellen der einzelnen St\u252 \'fccke, u. a.:
\par \pard\sl252\slmult1\fi0\li0\ql\ri0\sb0\sa165\itap0 Nr. 9,\plain \f1\scaps\lang1033\fs20  13, 14, 24, 26 \plain \f1\lang1033\fs20 und \plain \f1\scaps\lang1033\fs20 27: Caesarius Heisterbacensis\plain \f1\lang1033\fs20 : \plain \f1\i\lang1033\fs20 Mirac.\plain \f1\lang1033\fs20  = Die Fragmente der Libri VIII Miraculorum des Caesarius von Heisterbach, hg. von Aloys \plain \f1\scaps\lang1033\fs20 Meister \plain \f1\lang1033\fs20 (R\u246 \'f6mische Quartalschrift, XIV. Supplementbd.), Rom 1901. Nr. 1-9, 11, 14-18, 28, 31-33 und 36 in variierender Reihenfolge auch in der Hs. London, BL, Add. 18929 (14. Jh., Vorbesitz: Benediktinerkloster St. Peter Erfurt), 79\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 -86\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 , vgl. H. L. D. \plain \f1\scaps\lang1033\fs20 Ward\plain \f1\lang1033\fs20 , Catalogue of Romances in the Department of Manuscripts in the British Museum, London 1893, Bd. II, S. 129, 656-661. 
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 Nr. 1-4, 6, 31, 11, 17-18 sowie weitere Mirakel au\u223 \'dferdem in M\u252 \'fcnchen, BSB, {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Clm 28477}}\plain \f1\lang1033\fs20  (Erfurt?, Ende 14./Anf. 15. Jh., Vorbesitz: Erfurt, Kartause Salvatorberg), 32\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 -38\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 , vgl. \plain \f1\scaps\lang1033\fs20 Kudorfer\plain \f1\lang1033\fs20 , BSB M\u252 \'fcnchen IV/9, S. 26.
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 Daneben einzelne St\u252 \'fccke auch separat \u252 \'fcberliefert, im Folgenden nur stichprobenartig, v. a. bei den nicht bei \plain \f1\scaps\lang1033\fs20 Poncelet\plain \f1\lang1033\fs20  nachgewiesen St\u252 \'fccken, \u252 \'fcberpr\u252 \'fcft. 
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 - Nr. 1, 3, 4, 27, 28 auch in Klosterneuburg, Augustiner-Chorherrenstift, {\field{\*\fldinst HYPERLINK "hida://5007[1].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Cod. 131}}\plain \f1\lang1033\fs20  (Klosterneuburg, Ende 13. Jh.), 294\plain \f1\super\lang1033\fs20 rb-vb\plain \f1\lang1033\fs20 , vgl. https://manuscripta.at/hs_detail.php?ID=301;
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 - Nr. 2, 5, 7, 8, 12, 18, 20, 28, 30, 35 in Weimar, HAAB, {\field{\*\fldinst HYPERLINK "hida://5007[2].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Fol 23}}\plain \f1\lang1033\fs20  (Deutschland, Mitte 15. Jh., Vorbesitz: Erfurt, Collegium universitatis), 297\plain \f1\super\lang1033\fs20 vb\plain \f1\lang1033\fs20 -310\plain \f1\super\lang1033\fs20 rb\plain \f1\lang1033\fs20 , vgl. \plain \f1\scaps\lang1033\fs20 Bushey\plain \f1\lang1033\fs20 , Weimar I, S. 113-116; http://www.manuscripta-mediaevalia.de/dokumente/html/obj31572773;
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 - Nr. 12, 19, 29, 32, 34, 37 auch in Kremsm\u252 \'fcnster, Benediktinerstift, {\field{\*\fldinst HYPERLINK "hida://5007[3].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 CC 51}}\plain \f1\lang1033\fs20  (Bayern-\u214 \'d6sterreich, 2. H\u228 \'e4lfte 14. Jh.), 147\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 -158\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 , vgl. http://www.manuscripta-mediaevalia.de/dokumente/html/obj90799895,T.}

