\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 201\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 -202\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24  [hinzugef\u252 \'fcgtes Doppelbl.:] {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Jacobus de Lausanna}}\plain \f1\b\lang1033\fs24 :\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Sermo in vigilia Paschae}}\plain \f1\lang1033\fs24 . \plain \f1\lang1033\fs24\cf6  
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 [G]\plain \f1\i\lang1033\fs24 lloria \plain \f1\lang1033\fs24 (!) \plain \f1\i\lang1033\fs24 domini apparuit in nube: Exodus 24\u176 \'b0\plain \f1\lang1033\fs24  (Ex 16,10). \plain \f1\i\lang1033\fs24 Persona nouiter educta de carcere non potest statim videre clarum lumen, quia carcer ledit oculos\plain \f1\lang1033\fs24 .\plain \f1\i\lang1033\fs24  Et secundum Augustinum oculis egris odiosa est lux\plain \f1\lang1033\fs24  ... - ... \plain \f1\i\lang1033\fs24 humilem spiritu suscipiet gloria\plain \f1\lang1033\fs24 . \plain \f1\i\lang1033\fs24 Quod nobis concedat etc..
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20 Die Predigt bei \plain \f1\scaps\lang1033\fs20 Schneyer\plain \f1\lang1033\fs20 , Repertorium III, S. 72, unter den Sermones de tempore des Jacobus de Losanna OP als Nr. 216 (T27: In vigilia Paschae) verzeichnet. Vgl. auch J. B. \plain \f1\scaps\lang1033\fs20 Schneyer\plain \f1\lang1033\fs20 , Eine Sermonesliste des Jacobus de Lausanne OP, in: Recherches de de th\u233 \'e9ologie ancienne et m\u233 \'e9di\u233 \'e9vale XXVII (1960), S. 76-132, hier S. 88 (Sermones de tempore 145 [uig. pasc.]). Zur \u220 \'dcberlieferung der Sermones de tempore (ohne diese Hs.) vgl. \plain \f1\scaps\lang1033\fs20 Schneyer\plain \f1\lang1033\fs20 , Repertorium III, S. 88f. (ca. 100 Hss.); \plain \f1\scaps\lang1033\fs20 Kaeppeli\plain \f1\lang1033\fs20  II, S. 326f., Nr. 2088 (13 bei \plain \f1\scaps\lang1033\fs20 Schneyer\plain \f1\lang1033\fs20  nicht aufgef\u252 \'fchrte Hss.). Auf dem Titelschild (s. o. Geschichte) diese Predigt hingegen als \plain \f1\i\lang1033\fs20 ... sermo in Cena domini.\plain \f1\lang1033\fs20  verzeichnet.
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 Zum Autor (Mitglied des Pariser Dominikanerkonvents St. Jakob Paris, 1317 Lic. theol., Ordensprovinzial der Provinz Francia, \u8224 \'86 1321) vgl. \plain \f1\scaps\lang1033\fs20 Kaeppeli\plain \f1\lang1033\fs20  II, S. 323-329; Manfred \plain \f1\scaps\lang1033\fs20 Gerwing\plain \f1\lang1033\fs20 , Art. \u8222 \'84J. v. Lausanne OP\ldblquote , in: LexMa V (1991), Sp. 259 und Isnard Wilhelm \plain \f1\scaps\lang1033\fs20 Frank\plain \f1\scaps\lang1033\fs20 , \plain \f1\lang1033\fs20 Art. \u8222 \'84Jakob v. Lausanne\ldblquote , in: LThK V (1996), Sp. 728. Zu Bibelkommentaren des Jacobus de Lausanne vgl. \plain \f1\scaps\lang1033\fs20 Stegm\plain \f1\scaps\lang1033\fs20 \u252 \'fc\plain \f1\scaps\lang1033\fs20 ller\plain \f1\lang1033\fs20 , {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 RB III und IX.1, 3887-3969.}}}

