\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f2\lang1033\fs24 (113\plain \f2\super\lang1033\fs24 r\plain \f2\lang1033\fs24 -140\plain \f2\super\lang1033\fs24 v\plain \f2\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f2\b\lang1033\fs24\chcbpat18 Sequentiar}}\plain \f2\lang1033\fs24 , unvollst.
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 (113\plain \f2\super\lang1033\fs24 r\plain \f2\lang1033\fs24 ) [\plain \f2\b\lang1033\fs24 In Nativitate Christi\plain \f2\lang1033\fs24  ad primam missam], \plain \f2\i\lang1033\fs24 >{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f2\i\lang1033\fs24\chcbpat18 G<rates nunc omnes / reddamus domino deo}}\plain \f2\i\lang1033\fs24  ...\plain \f2\lang1033\fs24  ({\field{\*\fldinst HYPERLINK "hida://bezlit[1].8330/?u"}{\fldrslt \plain \f2\lang1033\fs24\chcbpat18 AH 53, Nr. 10}}\plain \f2\lang1033\fs24 );
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 (113\plain \f2\super\lang1033\fs24 r-v\plain \f2\lang1033\fs24 ) [\plain \f2\b\lang1033\fs24 In Nativitate Christi\plain \f2\lang1033\fs24  ad secundam missam], \plain \f2\i\lang1033\fs24 >E<ya, recolamus laudibus piis digna. / {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f2\i\lang1033\fs24\chcbpat18 >H<uius diei carmina, / in qua nobis lux}}\plain \f2\i\lang1033\fs24  ...\plain \f2\lang1033\fs24  (AH 53, Nr. 16);
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 (113\plain \f2\super\lang1033\fs24 v\plain \f2\lang1033\fs24 -114\plain \f2\super\lang1033\fs24 r\plain \f2\lang1033\fs24 ) [\plain \f2\b\lang1033\fs24 In Nativitate Christi\plain \f2\lang1033\fs24 ] \plain \f2\i\lang1033\fs24 >Ad summam missam<\plain \f2\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f2\i\lang1033\fs24\chcbpat18 >N<atus ante secula / dei filius, / inuisibilis, interminus}}\plain \f2\i\lang1033\fs24  ... \plain \f2\lang1033\fs24 (AH 53, Nr. 15, Autor: \plain \f2\scaps\lang1033\fs24 Notker Balbulus\plain \f2\lang1033\fs24 );
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 (114\plain \f2\super\lang1033\fs24 r-v\plain \f2\lang1033\fs24 ) \plain \f2\i\lang1033\fs24 >\plain \f2\b\i\lang1033\fs24 De sancto Stephano\plain \f2\i\lang1033\fs24 < \plain \f2\lang1033\fs24 (26.12.), (114\plain \f2\super\lang1033\fs24 v\plain \f2\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f2\i\lang1033\fs24\chcbpat18 >H<anc concordi famulatu / colamus sollempnitatem}}\plain \f2\i\lang1033\fs24  ... \plain \f2\lang1033\fs24 (AH 53, Nr. 215, Autor: \plain \f2\scaps\lang1033\fs24 Notker Balbulus\plain \f2\lang1033\fs24 );
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f2\lang1033\fs20 vom Schreiber am linken Blattrand querst\u228 \'e4ndig Schluss von Str. 10 erg\u228 \'e4nzt: \plain \f2\i\lang1033\fs20 ad dextram summi / patris ostendo\plain \f2\lang1033\fs20  ...;
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f2\lang1033\fs24 (114\plain \f2\super\lang1033\fs24 v\plain \f2\lang1033\fs24 -115\plain \f2\super\lang1033\fs24 r\plain \f2\lang1033\fs24 ) \plain \f2\i\lang1033\fs24 >\plain \f2\b\i\lang1033\fs24 De sancto Iohanne ewangelista\plain \f2\i\lang1033\fs24 < \plain \f2\lang1033\fs24 (27.12.), {\field{\*\fldinst HYPERLINK "hida://5650[4].5666l/?u"}{\fldrslt \plain \f2\i\lang1033\fs24\chcbpat18 >I<ohannes, Ihesu Cristo / multum dilecte virgo}}\plain \f2\i\lang1033\fs24 , ...\plain \f2\lang1033\fs24  (AH 53, Nr. 168, Autor: \plain \f2\scaps\lang1033\fs24 Notker Balbulus\plain \f2\lang1033\fs24 );
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 (115\plain \f2\super\lang1033\fs24 r\plain \f2\lang1033\fs24 -116\plain \f2\super\lang1033\fs24 r\plain \f2\lang1033\fs24 ) \plain \f2\i\lang1033\fs24 >\plain \f2\b\i\lang1033\fs24 In Epyphania domini\plain \f2\i\lang1033\fs24 <\plain \f2\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://5650[5].5666l/?u"}{\fldrslt \plain \f2\i\lang1033\fs24\chcbpat18 >F<esta Christi omnis / christianitas celebret}}\plain \f2\i\lang1033\fs24  ...\plain \f2\lang1033\fs24  (AH 53, Nr. 29, Autor: \plain \f2\scaps\lang1033\fs24 Notker Balbulus\plain \f2\lang1033\fs24 );
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 (116\plain \f2\super\lang1033\fs24 r-v\plain \f2\lang1033\fs24 ) \plain \f2\i\lang1033\fs24 >\plain \f2\b\i\lang1033\fs24 In Conuersione sancti Pauli\plain \f2\i\lang1033\fs24 < \plain \f2\lang1033\fs24 (25.01.),\plain \f2\i\lang1033\fs20  {\field{\*\fldinst HYPERLINK "hida://5650[6].5666l/?u"}{\fldrslt \plain \f2\i\lang1033\fs24\chcbpat18 >D<ixit dominus: ex Basan conuertam / conuertam in profundum maris}}\plain \f2\i\lang1033\fs24  ...\plain \f2\lang1033\fs24  ({\field{\*\fldinst HYPERLINK "hida://bezlit[6].8330/?u"}{\fldrslt \plain \f2\lang1033\fs24\chcbpat18 AH 50, Nr. 269}}\plain \f2\lang1033\fs24 , Autor: \plain \f2\scaps\lang1033\fs24 Godescalcus Lintpurgenis\plain \f2\lang1033\fs24 );
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 (116\plain \f2\super\lang1033\fs24 v\plain \f2\lang1033\fs24 -117\plain \f2\super\lang1033\fs24 v\plain \f2\lang1033\fs24 ) \plain \f2\i\lang1033\fs24 >\plain \f2\b\i\lang1033\fs24 In Purificacione sancte Marie\plain \f2\i\lang1033\fs24 < \plain \f2\lang1033\fs24 (02.02.), {\field{\*\fldinst HYPERLINK "hida://5650[7].5666l/?u"}{\fldrslt \plain \f2\i\lang1033\fs24\chcbpat18 >C<oncentu parili / hic te, Maria, / ueneratur populus}}\plain \f2\i\lang1033\fs24  ...\plain \f2\lang1033\fs24  (AH 53, Nr. 99, Autor: \plain \f2\scaps\lang1033\fs24 Notkerus Balbulus\plain \f2\lang1033\fs24 , mit Zusatzstr. 3:\plain \f2\scaps\lang1033\fs24  \plain \f2\i\lang1033\fs24 >S<anctissima corpore / castissima moribus ...\plain \f2\lang1033\fs24 );
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 (117\plain \f2\super\lang1033\fs24 v\plain \f2\lang1033\fs24 -118\plain \f2\super\lang1033\fs24 v\plain \f2\lang1033\fs24 ) \plain \f2\i\lang1033\fs24 >\plain \f2\b\i\lang1033\fs24 In Pascha\plain \f2\i\lang1033\fs24 <\plain \f2\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://5650[8].5666l/?u"}{\fldrslt \plain \f2\i\lang1033\fs24\chcbpat18 >L<Audes saluatori / uoce modulemur supplici}}\plain \f2\i\lang1033\fs24  ...\plain \f2\lang1033\fs24  (AH 53, Nr. 36, Autor: \plain \f2\scaps\lang1033\fs24 Notkerus Balbulus\plain \f2\lang1033\fs24 );
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 (118\plain \f2\super\lang1033\fs24 v\plain \f2\lang1033\fs24 -119\plain \f2\super\lang1033\fs24 r\plain \f2\lang1033\fs24 ) \plain \f2\i\lang1033\fs24 >\plain \f2\b\i\lang1033\fs24 Item in festo Pasche\plain \f2\i\lang1033\fs24 <\plain \f2\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://5650[9].5666l/?u"}{\fldrslt \plain \f2\i\lang1033\fs24\chcbpat18 >U<ictime paschali laudes / immolent christiani}}\plain \f2\i\lang1033\fs24  ...\plain \f2\lang1033\fs24  ({\field{\*\fldinst HYPERLINK "hida://bezlit[2].8330/?u"}{\fldrslt \plain \f2\lang1033\fs24\chcbpat18 AH 54, Nr. 7}}\plain \f2\lang1033\fs24 , Autor: \plain \f2\scaps\lang1033\fs24 Wipo\plain \f2\lang1033\fs24 ); interlinear Text einer \plain \f2\b\lang1033\fs24 Mariensequenz\plain \f2\lang1033\fs24  (Tempore paschali) auf diese Melodie nachgetragen (3. Viertel 15. Jh.): \plain \f2\i\lang1033\fs24 Virgini\plain \f2\lang1033\fs24  \plain \f2\i\lang1033\fs24 Marie laudes / intonent christiani. / {\field{\*\fldinst HYPERLINK "hida://5650[10].5666l/?u"}{\fldrslt \plain \f2\i\lang1033\fs24\chcbpat18 O beata domina, / tua per precamina / reconsilientur peccatores}}\plain \f2\i\lang1033\fs24 . ... \plain \f2\lang1033\fs24 (AH 54, Nr. 21)\plain \f2\i\lang1033\fs24 ;
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f2\lang1033\fs20 nach AH 54, Nr. 21, S. 32 ist diese Mariensequenz (mit den Varianten: Virgini Marie laudes concinant / intonent christiani ..., vgl. auch AH 54, Nr. 18) seit dem 13. Jh. h\u228 \'e4ufig in Dominikanerquellen \u252 \'fcberliefert, weshalb evtl. auf einen Autor aus dem Dominikanerorden zu schlie\u223 \'dfen ist;
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f2\lang1033\fs24 (119\plain \f2\super\lang1033\fs24 r\plain \f2\lang1033\fs24 -120\plain \f2\super\lang1033\fs24 r\plain \f2\lang1033\fs24 ) \plain \f2\i\lang1033\fs24 >\plain \f2\b\i\lang1033\fs24 De sancta cruce\plain \f2\i\lang1033\fs24 < \plain \f2\lang1033\fs24 (zu Inventio s. crucis, 03.05.),\plain \f2\i\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://5650[11].5666l/?u"}{\fldrslt \plain \f2\i\lang1033\fs24\chcbpat18 >L<audes crucis attollamus / nos, qui crucis exultamus}}\plain \f2\i\lang1033\fs24  ...\plain \f2\lang1033\fs24  (AH 54, Nr. 120);
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 (120\plain \f2\super\lang1033\fs24 v\plain \f2\lang1033\fs24 -121\plain \f2\super\lang1033\fs24 v\plain \f2\lang1033\fs24 ) \plain \f2\i\lang1033\fs24\cf1 >\plain \f2\b\i\lang1033\fs24\cf1 De sancto Johanne ewangelista\plain \f2\i\lang1033\fs24\cf1 <\plain \f2\lang1033\fs24\cf1  (zu Johannes ante portam latinam, 06.05.), {\field{\*\fldinst HYPERLINK "hida://5650[12].5666l/?u"}{\fldrslt \plain \f2\i\lang1033\fs24\chcbpat18\cf1 >U<erbum dei, deo natum, / quod nec factum nec creatum}}\plain \f2\i\lang1033\fs24\cf1  ...\plain \f2\lang1033\fs24\cf1  ();
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 (121\plain \f2\super\lang1033\fs24\cf1 v\plain \f2\lang1033\fs24\cf1 -122\plain \f2\super\lang1033\fs24\cf1 r\plain \f2\lang1033\fs24\cf1 ) \plain \f2\i\lang1033\fs24\cf1 >\plain \f2\b\i\lang1033\fs24\cf1 In Ascensione domini\plain \f2\i\lang1033\fs24\cf1 <\plain \f2\lang1033\fs24\cf1 ,{\field{\*\fldinst HYPERLINK "hida://5650[13].5666l/?u"}{\fldrslt \plain \f2\i\lang1033\fs24\chcbpat18\cf1  >S<ummi triumphum regis / prosequamur laude}}\plain \f2\i\lang1033\fs24\cf1  ...\plain \f2\lang1033\fs24\cf1  (AH 53, Nr. 67);
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 (122\plain \f2\super\lang1033\fs24\cf1 r\plain \f2\lang1033\fs24\cf1 -123\plain \f2\super\lang1033\fs24\cf1 r\plain \f2\lang1033\fs24\cf1 ) >\plain \f2\b\i\lang1033\fs24\cf1 De sancto spiritu\plain \f2\lang1033\fs24\cf1 <, (122\plain \f2\super\lang1033\fs24\cf1 v\plain \f2\lang1033\fs24\cf1 ) {\field{\*\fldinst HYPERLINK "hida://5650[14].5666l/?u"}{\fldrslt \plain \f2\i\lang1033\fs24\chcbpat18\cf1 >S<ancti spiritus / assit nobis gratia, / que corda nostra}}\plain \f2\i\lang1033\fs24\cf1  ...\plain \f2\lang1033\fs24\cf1  (AH 53, Nr. 70);}

