\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 140\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  [Nachtr\u228 \'e4ge:] 
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\b\lang1033\fs24 1. \plain \f1\i\lang1033\fs24 >\plain \f1\b\i\lang1033\fs24 Benediccio in ordinacione episcopi\plain \f1\i\lang1033\fs24 <\plain \f1\lang1033\fs24 . \plain \f1\i\lang1033\fs24 >D<eus, ad quem respicit sacerdotum sollercia,\plain \f1\lang1033\fs20  \plain \f1\i\lang1033\fs24 regnancium uictoria, populi disciplina ... - ... mereatur pastor consequi graciam, grex medelam. >A<men. Quod ipse \plain \f1\lang1033\fs24 [von anderer Hand erg\u228 \'e4nzt:]\plain \f1\i\lang1033\fs24  prestare dignetur, cuius regnum ...\plain \f1\lang1033\fs24 ;
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\b\lang1033\fs24 2. \plain \f1\lang1033\fs24 [letztes Viertel 15. Jh.:]\plain \f1\b\lang1033\fs24  Professformel f\u252 \'fcr eine Nonne\plain \f1\lang1033\fs24 . \plain \f1\i\lang1033\fs24 Ego soror \u183 \'b7N\u183 \'b7 renuncians seculo offero me omnipotenti deo et gloriosi uirgini Marie pollicens me semper in castitate et religione uicturam.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

